def _validate_drafting_document(document: Dict[str, Any]) -> Tuple[bool, Optional[str]]:
    """THE THREE CHECKS, ALL THREE THE DRAFTING LIBRARY'S. (ok, reason).

    The reason is the validator's OWN message, carried verbatim to the page:
    an INVALID document that does not say WHICH id, section and sentence broke
    it is indistinguishable from an empty one, which is the failure this cell
    exists to remove one level up."""
    import jsonschema

    from lib.research.drafting import pipeline as drafting_pipeline
    from lib.research.drafting import verbatim as drafting_verbatim

    with open(_drafting_schema_path(), "r", encoding="utf-8") as handle:
        schema = json.load(handle)
    try:
        jsonschema.validate(document, schema)
    except jsonschema.ValidationError as err:
        where = "/".join(str(part) for part in err.absolute_path) or "<document>"
        return False, "marking contract: {0}: {1}".format(where, err.message)

    indexed = drafting_pipeline.records_by_id(document.get("evidence_records"))
    source = {
        "accession": document.get("accession"),
        "document_sha256": (document.get("source") or {}).get("document_sha256"),
    }
    for section in document.get("sections") or []:
        section_id = section.get("section")
        for position, sentence in enumerate(section.get("sentences") or []):
            ok, reason = drafting_pipeline.validate_evidence(
                sentence.get("evidence"), indexed, source
            )
            if not ok:
                return False, "{0} sentence {1}: {2}".format(section_id, position, reason)
            verdict = drafting_verbatim.check_against_sources(
                sentence.get("quoted_spans"),
                drafting_pipeline.passage_texts_for(sentence["evidence"], indexed),
            )
            if verdict != "PASS":
                return False, (
                    "{0} sentence {1}: the verbatim gate REFUSES a quoted span against the "
                    "passage it cites ({2})".format(
                        section_id, position, ", ".join(sentence.get("evidence") or [])
                    )
                )
            if sentence.get("verbatim_check") != verdict:
                return False, (
                    "{0} sentence {1}: shipped verbatim_check {2!r}, the gate re-run against "
                    "the passage says {3!r}".format(
                        section_id, position, sentence.get("verbatim_check"), verdict
                    )
                )
    return True, None

